const businessScheduleKeys=['scheduleFrequency','scheduleCustom','scheduleStart','scheduleEndRule','scheduleEnd'];
function businessScheduleFields(){const v=k=>esc(uploadDraft[k]||'');return `<fieldset class="field full business-schedule" id="business-schedule" hidden disabled><legend>Requested schedule</legend><p class="help">Each scheduled draft will need your approval before it becomes an order. This form records a request only; no schedule is activated.</p><div class="fields"><div class="field"><label for="schedule-frequency">Frequency *</label><select id="schedule-frequency" name="scheduleFrequency" required><option value="">Select frequency</option>${['Weekly','Monthly','Custom'].map(x=>`<option ${uploadDraft.scheduleFrequency===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" id="schedule-custom-field" hidden><label for="schedule-custom">Custom interval *</label><input id="schedule-custom" name="scheduleCustom" value="${v('scheduleCustom')}" maxlength="120" placeholder="For example: every 2 weeks" required></div><div class="field"><label for="schedule-start">First draft date *</label><input id="schedule-start" name="scheduleStart" type="date" value="${v('scheduleStart')}" required><p class="help">When you want the first approval request. Delivery timing is agreed separately.</p></div><div class="field"><label for="schedule-end-rule">Schedule ends *</label><select id="schedule-end-rule" name="scheduleEndRule" required>${['Until cancelled','On a date'].map(x=>`<option ${uploadDraft.scheduleEndRule===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" id="schedule-end-field" hidden><label for="schedule-end">End date *</label><input id="schedule-end" name="scheduleEnd" type="date" value="${v('scheduleEnd')}" required></div></div><p class="help">Requested mode: prepare a draft for approval each time. Price, availability and delivery require confirmation. Pause, skip and cancellation controls will be available when scheduling is connected.</p></fieldset>`}
function bindBusinessSchedule(){if(formData.buyerType!=='Private business')return;const f=$('#document-enquiry');const panel=$('#business-schedule');function update(){const type=f.querySelector('[name="orderType"]:checked')?.value;const scheduled=type==='Scheduled repeat request';panel.hidden=!scheduled;panel.disabled=!scheduled;const custom=$('#schedule-frequency').value==='Custom';$('#schedule-custom-field').hidden=!custom;$('#schedule-custom').disabled=!scheduled||!custom;const dated=$('#schedule-end-rule').value==='On a date';$('#schedule-end-field').hidden=!dated;$('#schedule-end').disabled=!scheduled||!dated;const reference=$('#upload-previousReference');reference.closest('.field').hidden=type!=='Repeat purchase';reference.disabled=type!=='Repeat purchase';captureUpload()};f.querySelectorAll('[name="orderType"]').forEach(x=>x.addEventListener('change',update));$('#schedule-frequency').addEventListener('change',update);$('#schedule-end-rule').addEventListener('change',update);update()}
function cleanBusinessSchedule(buyer){if(buyer.buyerType!=='Private business'||buyer.orderType!=='Scheduled repeat request'){for(const k of businessScheduleKeys)delete buyer[k]}else{if(buyer.scheduleFrequency!=='Custom')delete buyer.scheduleCustom;if(buyer.scheduleEndRule!=='On a date')delete buyer.scheduleEnd}if(buyer.buyerType==='Private business'&&buyer.orderType!=='Repeat purchase')delete buyer.previousReference;return buyer}
function validateBusinessSchedule(){if(formData.buyerType!=='Private business'||uploadDraft.orderType!=='Scheduled repeat request')return '';const today=new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'});if(uploadDraft.scheduleStart<today)return 'Choose a current or future first draft date.';if(uploadDraft.scheduleEndRule==='On a date'&&uploadDraft.scheduleEnd<uploadDraft.scheduleStart)return 'The schedule end date must be on or after the first draft date.';return ''}
function scheduleSummary(b){if(b.buyerType!=='Private business'||b.orderType!=='Scheduled repeat request')return '';const field=(label,value)=>value?`<div><dt>${label}</dt><dd>${esc(value)}</dd></div>`:'';return `<section><h2>Requested repeat schedule</h2><dl>${field('Frequency',b.scheduleFrequency)}${field('Custom interval',b.scheduleCustom)}${field('First draft date',b.scheduleStart)}${field('Ends',b.scheduleEndRule)}${field('End date',b.scheduleEnd)}${field('Approval','Required for every draft')}</dl><p>Schedule request only. No schedule has been activated and no recurring order has been placed.</p></section>`}
function businessPurchaseType(){const previous=uploadDraft.orderType;const selected=['Once-off quote','Once-off purchase'].includes(previous)?'Once-off purchase':['Repeat requirement','Repeat purchase'].includes(previous)?'Repeat purchase':previous==='Scheduled repeat request'?previous:'';return `<fieldset class="field full business-purchase-type"><legend>Purchase type *</legend><div class="purchase-type-options">${['Once-off purchase','Repeat purchase','Scheduled repeat request'].map((type,i)=>`<label for="business-purchase-${i}"><input id="business-purchase-${i}" type="radio" name="orderType" value="${type}" ${selected===type?'checked':''} required><span>${type}</span></label>`).join('')}</div></fieldset>`}
// Enquiries are prepared locally. Received/accepted/order states belong to the future server.
function orderingJourney(buyerType){if(!['Private business','Government / public entity'].includes(buyerType))return '';const government=buyerType==='Government / public entity';return `<div class="ordering-journey"><h2>How ordering works</h2><ol><li><strong>Requirements review</strong><span>Lepetse checks specifications, availability and delivery requirements after receiving your enquiry.</span></li><li><strong>${government?'RFQ response':'Itemised quotation'}</strong><span>${government?'The quotation and supporting documents follow the institution’s official submission instructions.':'Pricing, quote validity, delivery charges and proposed payment terms are provided for review.'}</span></li><li><strong>${government?'Official authorisation':'Your approval'}</strong><span>${government?'Lepetse verifies the official purchase order or required authorisation before confirming an order.':'Approve the quotation by email or provide a purchase order where required. Payment terms are agreed per customer.'}</span></li><li><strong>Order confirmation and delivery</strong><span>Lepetse confirms the order once authorisation and agreed payment conditions are met. Delivery and invoicing follow the agreed terms.</span></li></ol></div>`}
function approvalNote(buyerType){if(buyerType==='Private business')return '<p class="help">Approve the quotation by email or provide a purchase order where required. Payment terms are agreed per customer before order confirmation.</p>';if(buyerType==='Government / public entity')return '<p class="help">Order confirmation follows verification of the official purchase order or required authorisation and the agreed terms.</p>';return ''}
function uploadBuyerSelector(){const buyer=new URLSearchParams(location.hash.split("?")[1]||"").get("buyer");if(["business","government","schools"].includes(buyer))return "";return `<div class="field enquiry-buyer"><label for="upload-buyerType">Buyer type *</label><select id="upload-buyerType" name="buyerType" required>${['Private business','Government / public entity'].map(x=>`<option ${formData.buyerType===x?'selected':''}>${x}</option>`).join('')}</select><p class="help">No account is needed to prepare a quotation request.</p></div>`}
const basketStorageKey='lepetse.catalogueBasket.v1';
let basketStorageUnavailable=false;
function restoreBasket(){try{const raw=JSON.parse(localStorage.getItem(basketStorageKey)||'[]');if(!Array.isArray(raw))return [];return raw.slice(0,250).flatMap(x=>{const p=products.find(p=>p.id===x.id)||retiredProducts.find(p=>p.id===x.id);return p&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=999999?[{productId:p.id,description:validatedSchoolMeta(x.school,p.id)?schoolBasketDescription(p,validatedSchoolMeta(x.school,p.id),x.quantity):`${p.name} — ${p.summary}`,quantity:x.quantity,unit:p.unit,...(validatedSchoolMeta(x.school,p.id)?{school:validatedSchoolMeta(x.school,p.id)}:{})}]:[]})}catch{return []}}
function saveBasket(){try{const lines=items.filter(x=>products.some(p=>p.id===x.productId)||retiredProducts.some(p=>p.id===x.productId)).map(x=>({id:x.productId,quantity:Number(x.quantity),...(validatedSchoolMeta(x.school,x.productId)?{school:validatedSchoolMeta(x.school,x.productId)}:{})}));if(lines.length)localStorage.setItem(basketStorageKey,JSON.stringify(lines));else localStorage.removeItem(basketStorageKey)}catch{basketStorageUnavailable=true}}
function showAdded(p,quantity,total){const d=document.getElementById('basket-dialog');d.innerHTML=`<div class="confirmation-mark" aria-hidden="true">✓</div><h2 id="basket-dialog-title">Added to your ${rfqBuyer()?'RFQ':'quote'} basket</h2><p class="added-name">${esc(p.name)}</p><dl><div><dt>Quantity added</dt><dd>${quantity}</dd></div><div><dt>Ordering unit</dt><dd>${esc(p.unit)}</dd></div><div><dt>Now in your basket</dt><dd>${total} × ${esc(p.unit)}</dd></div></dl><div class="dialog-actions"><button class="btn outline" id="keep-browsing">Continue browsing</button><a class="btn dark" href="${rfqHref('basket')}" id="see-basket">${rfqBuyer()?'View RFQ basket':'View basket'}</a></div>`;d.showModal();$('#keep-browsing').onclick=()=>d.close();$('#see-basket').onclick=()=>d.close();$('#keep-browsing').focus()}
function clearBasketPrompt(){const d=document.getElementById('basket-dialog');d.innerHTML='<h2 id="basket-dialog-title">Clear your quote basket?</h2><p>This removes saved catalogue selections from this device. Contact details and attachments are separate.</p><div class="dialog-actions"><button class="btn outline" id="cancel-clear">Keep basket</button><button class="btn dark" id="confirm-clear">Clear basket</button></div>';d.showModal();$('#cancel-clear').onclick=()=>d.close();$('#confirm-clear').onclick=()=>{items=[];saveBasket();updateCount();d.close();main.innerHTML=basket();bindBasket();main.querySelector('h1')?.focus()};$('#cancel-clear').focus()}
const facetKeys={paper:['Size','Weight','Colour'],books:['Size','Pages','Sheets','Ruling','Binding'],pens:['Ink colour','Tip','Grade'],files:['Size','Spine width','Pockets','Material'],art:['Colours','Size','Type'],ruler:['Length','Material','Type'],calc:['Display','Type']};
let uploadDraft={},uploadFiles=[];
function uploadPage(){const requestedBuyer=new URLSearchParams(location.hash.split('?')[1]||'').get('buyer');if(requestedBuyer==='schools')formData.buyerType='School / education';else if(requestedBuyer==='government')formData.buyerType='Government / public entity';else if(requestedBuyer==='business')formData.buyerType='Private business';else formData.buyerType='Private business';const government=formData.buyerType==='Government / public entity';const school=formData.buyerType==='School / education';const v=(n)=>esc(uploadDraft[n]||'');return `${pageHero(government?'Government RFQ enquiry':school?'School list enquiry':'Document enquiry',government?'Upload your RFQ pack':school?'Upload your school list':'Upload your stationery list','Attach your document and complete the details below. No product entry is needed.')}<section class="section"><div class="wrap upload-layout"><form id="document-enquiry">${uploadBuyerSelector()}<fieldset class="upload"><legend>Your documents *</legend><label for="document-files">Stationery list, school list or RFQ</label><input id="document-files" type="file" multiple accept=".pdf,.xlsx,.csv,.docx,.jpg,.jpeg,.png"><p class="help">Up to 5 files, 10 MB each. PDF, XLSX, CSV, DOCX, JPG or PNG. Attachments stay on your device.</p><p id="document-file-list">${uploadFiles.map(f=>esc(f.name)).join(', ')}</p><button type="button" class="clear-filters" id="remove-documents">Remove documents</button></fieldset><div class="fields">${[['organisation','Organisation','text',true],['contact','Contact person','text',true],['email','Email address','email',true],['phone','Telephone','tel',false],['town','Delivery town / city','text',true],['postcode','Postcode','text',true]].map(([n,l,t,req])=>`<div class="field"><label for="upload-${n}">${n==='organisation'?(government?'Issuing institution':school?'School name':l):l}${req?' *':''}</label><input id="upload-${n}" name="${n}" type="${t}" value="${v(n)}" ${req?'required':''} ${n==='postcode'?'pattern="[0-9]{4}" title="Four-digit South African postcode"':''}></div>`).join('')}<div class="field"><label for="upload-province">Province *</label><select id="upload-province" name="province" required><option value="">Select a province</option>${['Eastern Cape','Free State','Gauteng','KwaZulu-Natal','Limpopo','Mpumalanga','North West','Northern Cape','Western Cape'].map(p=>`<option ${uploadDraft.province===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="field"><label for="upload-date">Required delivery date *</label><input id="upload-date" name="date" type="date" value="${v('date')}" required></div>${school?`<div class="field"><label for="upload-grade">Grade, class or programme *</label><input id="upload-grade" name="grade" value="${v('grade')}" required></div><div class="field"><label for="upload-learners">Number of learners / packs *</label><input id="upload-learners" name="learners" type="number" min="1" max="999999" step="1" value="${v('learners')}" required></div><div class="field"><label for="upload-quantityBasis">Quantities on your list are *</label><select id="upload-quantityBasis" name="quantityBasis" required><option value="">Select quantity basis</option>${['Per learner / pack','Totals for the whole order','Mixed — explained in the list'].map(x=>`<option ${uploadDraft.quantityBasis===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="upload-packing">Packing requested</label><select id="upload-packing" name="packing">${['Bulk supply','Individual learner packs','Please discuss with me'].map(x=>`<option ${uploadDraft.packing===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label for="upload-labelling">Pack labelling instructions (optional)</label><input id="upload-labelling" name="labelling" value="${v('labelling')}" placeholder="For example: grade or class labels"><p class="help">Please avoid uploading learner names unless needed. Packing and labelling require confirmation.</p></div>`:''}${formData.buyerType==='Private business'?businessPurchaseType()+businessScheduleFields():`<div class="field"><label for="upload-orderType">Requirement type</label><select id="upload-orderType" name="orderType"><option value="">Select if applicable</option>${['Once-off quote','Repeat requirement','Regular supply'].map(x=>`<option ${uploadDraft.orderType===x?'selected':''}>${x}</option>`).join('')}</select></div>`}${[['previousReference','Previous order / quote reference'],['poNumber','Purchase-order reference'],['costCentre','Cost centre / department']].map(([n,l])=>`<div class="field"><label for="upload-${n}">${l} (optional)</label><input id="upload-${n}" name="${n}" value="${v(n)}" maxlength="120"></div>`).join('')}<div class="field"><label for="upload-alternatives">Alternative brands</label><select id="upload-alternatives" name="alternatives">${['Please confirm with me','Accept suitable alternatives','Specified brands only'].map(x=>`<option ${uploadDraft.alternatives===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="upload-reference">RFQ reference${government?' *':' (if applicable)'}</label><input id="upload-reference" name="reference" value="${v('reference')}" ${government?'required':''}></div><div class="field"><label for="upload-deadline">Quote closing deadline (SAST)${government?' *':' (if applicable)'}</label><input id="upload-deadline" name="deadline" type="datetime-local" value="${v('deadline')}" ${government?'required':''}></div>${government?`<div class="field full"><label for="upload-channel">Official submission instructions / channel *</label><input id="upload-channel" name="channel" value="${v('channel')}" required></div><div class="field full"><label for="upload-briefing">Mandatory briefing and addenda (if applicable)</label><input id="upload-briefing" name="briefing" value="${v('briefing')}"></div>`:''}<div class="field full"><label for="upload-notes">Delivery sites or additional instructions</label><textarea id="upload-notes" name="notes">${v('notes')}</textarea></div></div><p id="upload-error" class="error" role="alert"></p><button class="btn dark" type="submit">Review enquiry</button></form><aside><h2>Quotation request</h2><p>Use your document as the specification. Quote-basket products are kept separate.</p>${approvalNote(formData.buyerType)}<p class="help">Prepare and review your summary, then email it with the original documents. Nothing is sent automatically and no order is placed.</p></aside></div></section>`}
function uploadBuyerData(){const buyer={...uploadDraft,buyerType:formData.buyerType};if(buyer.buyerType!=='Government / public entity')for(const key of ['channel','briefing'])delete buyer[key];if(buyer.buyerType!=='School / education')for(const key of ['grade','learners','quantityBasis','packing','labelling'])delete buyer[key];return cleanBusinessSchedule(buyer)}
function captureUpload(){const f=$('#document-enquiry');if(f)new FormData(f).forEach((v,k)=>{if(typeof v==='string')uploadDraft[k]=v.trim()})}
function bindUpload(){const f=$('#document-enquiry');f.oninput=captureUpload;bindBusinessSchedule();const buyerSelect=$('#upload-buyerType');if(buyerSelect)buyerSelect.onchange=e=>{captureUpload();formData.buyerType=e.target.value;const buyer={"Private business":'business',"Government / public entity":'government',"School / education":'schools'}[formData.buyerType];history.replaceState(null,'','#upload'+(buyer?'?buyer='+buyer:''));main.innerHTML=uploadPage();bindUpload();applyPageBanner('upload');main.querySelector('h1')?.focus()};$('#document-files').onchange=e=>{const files=[...e.target.files];if(files.length>5||files.some(f=>f.size>10*1024*1024||!/\.(pdf|xlsx|csv|docx|jpe?g|png)$/i.test(f.name))){e.target.value='';$('#upload-error').textContent='Choose up to five supported files, each no larger than 10 MB.';return}uploadFiles=files;$('#document-file-list').textContent=files.map(f=>f.name).join(', ');$('#upload-error').textContent=''};$('#remove-documents').onclick=()=>{uploadFiles=[];$('#document-files').value='';$('#document-file-list').textContent=''};f.onsubmit=e=>{e.preventDefault();captureUpload();let err=validateBusinessSchedule();if(err){$('#upload-error').textContent=err;return}if(!uploadFiles.length)err='Attach at least one document before continuing.';else if(uploadDraft.date<new Date().toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'}))err='Choose a current or future delivery date.';else if(uploadDraft.deadline&&new Date(uploadDraft.deadline+'+02:00')<new Date())err='The quote closing deadline has passed. Check the date and time.';$('#upload-error').textContent=err;if(err)return;showEnquiry({buyer:uploadBuyerData(),items:[],attachments:uploadFiles.map(f=>({name:f.name,size:f.size}))},()=>{main.innerHTML=uploadPage();bindUpload()})}}
function enquiryDocument(s){const b=s.buyer;const field=(l,v)=>v?`<div><dt>${l}</dt><dd>${esc(v)}</dd></div>`:'';return `<article class="enquiry-document"><div class="document-heading"><strong>LEPETSE</strong><span>Prepared enquiry · not sent</span></div><h1>Stationery enquiry summary</h1><p class="document-date">Prepared ${new Date().toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'})} SAST</p>${b.deliveryStreet?rfqCompactDocument(b):`<section><h2>Buyer and contact</h2><dl>${field('Organisation',b.organisation)}${field('Contact',b.contact)}${field('Email',b.email)}${field('Telephone',b.phone)}${field('Buyer type',b.buyerType)}${field('Grade / class',b.grade)}${field('Learners / packs',b.learners)}${field('Quantity basis',b.quantityBasis)}${field('Packing requested',b.packing)}${field('Labelling instructions',b.labelling)}${field('Order type',b.orderType)}${field('Previous order / quote',b.previousReference)}${field('Purchase-order reference',b.poNumber)}${field('Cost centre / department',b.costCentre)}</dl></section>${scheduleSummary(b)}<section><h2>Delivery and timing</h2><dl>${field('Location',[b.town,b.province,b.postcode].filter(Boolean).join(', '))}${field('Number of sites',b.sites)}${field(b.deliveryStreet?'Requested delivery date':'Required date',b.date)}${field('Date flexibility',b.timing)}${field('RFQ reference',b.reference)}${field('Closing deadline',b.deadline?b.deadline.replace('T',' ')+' SAST':'')}${field('Submission channel',b.channel)}${field('Mandatory briefing',b.briefing)}</dl></section>${rfqDeliveryDocument(b)}`}<section><h2>${s.items.length?'Item requirements':'Document requirements'}</h2>${s.items.length?`<div class="table-scroll"><table><thead><tr><th>Item description / specification</th><th>Quantity</th><th>Ordering unit</th></tr></thead><tbody>${s.items.map(x=>`<tr><td>${esc(x.description)}</td><td>${esc(x.quantity)}</td><td>${esc(x.unit)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Use the attached document list below as the item specification.</p>'}${b.alternatives?`<p>Alternatives: ${esc(b.alternatives)}</p>`:''}</section>${b.notes?`<section><h2>Additional instructions</h2><p class="preserve-lines">${esc(b.notes)}</p></section>`:''}<section><h2>Documents</h2>${s.attachments.length?`<ul>${s.attachments.map(f=>`<li>${esc(f.name)} (${Math.ceil(f.size/1024)} KB)</li>`).join('')}</ul><p>Original attachments are not embedded. Attach them separately when sharing this enquiry.</p>`:'<p>No documents attached.</p>'}</section>${approvalNote(b.buyerType)}<p class="document-disclaimer">This is a prepared request, not a quotation, purchase order or confirmation of stock. Prices, applicable VAT, delivery and payment terms require confirmation. Nothing has been sent to Lepetse.</p></article>`}
function showEnquiry(summary,onEdit){const doc=enquiryDocument(summary);main.innerHTML=`<section class="section summary-view"><div class="wrap"><div class="enquiry-actions"><div><h2>Your enquiry is prepared — not sent</h2><p>Download a formatted copy or print it. You can save as PDF in the print dialog.</p></div><div><button class="btn dark" id="download-summary">Download enquiry</button><button class="btn outline" id="print-summary">Print / save as PDF</button><button class="btn outline" id="edit-summary">Edit details</button><a class="btn dark" id="email-enquiry">Open email draft</a></div></div>${doc}</div></section>`;const buyer=summary.buyer;const emailText=['Stationery enquiry',`Organisation: ${buyer.organisation||''}`,`Contact: ${buyer.contact||''}`,`Email: ${buyer.email||''}`,`Telephone: ${buyer.phone||''}`,`Buyer type: ${buyer.buyerType||''}`,`Alternative brands: ${buyer.alternatives||''}`,`Requirement: ${buyer.orderType||''}`,...(buyer.orderType==='Scheduled repeat request'?[`Requested frequency: ${buyer.scheduleFrequency||''}`,`Custom interval: ${buyer.scheduleCustom||''}`,`First draft date: ${buyer.scheduleStart||''}`,`Schedule ends: ${buyer.scheduleEndRule||''} ${buyer.scheduleEnd||''}`,'Approval required for each draft. Schedule request only; not activated.']:[]),`RFQ reference: ${buyer.reference||''}`,`Closing deadline (SAST): ${(buyer.deadline||'').replace('T',' ')}`,`Official submission instructions: ${buyer.channel||''}`,`Briefing / addenda: ${buyer.briefing||''}`,`Grade / class: ${buyer.grade||''}`,`Learners / packs: ${buyer.learners||''}`,`Quantity basis: ${buyer.quantityBasis||''}`,`Packing requested: ${buyer.packing||''}`,`Labelling: ${buyer.labelling||''}`,`Previous reference: ${buyer.previousReference||''}`,`PO reference: ${buyer.poNumber||''}`,`Cost centre: ${buyer.costCentre||''}`,`Delivery: ${[buyer.town,buyer.province,buyer.postcode].filter(Boolean).join(', ')}`,`Requested delivery date: ${buyer.date||''}`,...rfqDeliveryEmail(buyer),'',...summary.items.map(x=>`${x.description}: ${x.quantity} ${x.unit}`),'',buyer.notes||'','Documents: '+summary.attachments.map(f=>f.name).join(', '),'Please attach the downloaded enquiry summary and original documents before sending.'].join('\n');$('#email-enquiry').href='mailto:admin@lepetse.co.za?subject='+encodeURIComponent('Stationery enquiry — '+(buyer.organisation||'Business request'))+'&body='+encodeURIComponent(emailText);$('.enquiry-actions>div:first-child p').textContent='Download your summary, then open an email draft. Attach the summary and original files before sending. Nothing is sent automatically. This is a quotation request, not an order.';$('#edit-summary').onclick=onEdit;$('#print-summary').onclick=()=>window.print();$('#download-summary').onclick=()=>{const styles=document.getElementById('summary-styles').textContent;const html='<!doctype html><html lang="en-ZA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Lepetse stationery enquiry</title><style>'+styles+'</style></head><body><div class="enquiry-actions standalone-actions"><button onclick="window.print()">Print / save as PDF</button></div>'+doc+'</body></html>';const blob=new Blob([html],{type:'text/html;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Lepetse-stationery-enquiry.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};main.focus();window.scrollTo(0,0)}
